                  "must_not": [
                    {
                      "wildcard": {
                        "transaction.name": "google*"
                      }
                    }
                  ]
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations"
      },
      "transform": [
        {
          "type": "formula",
          "as": "availability",
          "expr": "datum.total_count.doc_count > 0 ? ((datum.success_count.doc_count + datum.server_error_count.doc_count) / datum.total_count.doc_count) * 100 : 0"
