	"$schema": "https://vega.github.io/schema/vega/v5.json",
	"autosize": {
		"type": "fit",
		"contains": "padding"
	},
	"data": [
		{
			"name": "services",
			"url": {
				"%context%": true,
				"%timefield%": "@timestamp",
				"index": "traces-apm*",
				"body": {
					"size": 0,
					"aggs": {
						"services": {
							"terms": {
								"field": "ci.name",
								"size": 5000
							},
							"aggs": {
								"total": {
									"filter": {
										"bool": {
											"must_not": [
												{
													"wildcard": {
														"transaction.name": "google*"
													}
												}
											]
										}
									}
								},
								"success": {
									"filter": {
										"bool": {
											"must": [
												{
													"term": {
														"event.outcome": "success"
													}
												}
											],
											"must_not": [
												{
													"wildcard": {
														"transaction.name": "google*"
													}
												}
											]
										}
									}
								},
								"error_5xx": {
									"filter": {
										"bool": {
											"must": [
												{
													"range": {
														"http.response.status_code": {
															"gte": 500
														}
													}
												}
											],
											"must_not": [
												{
													"wildcard": {
														"transaction.name": "google*"
													}
												}
											]
										}
									}
								}
							}
						}
					}
				}
			},
			"format": {
				"property": "aggregations.services.buckets"
			},
			"transform": [
				{
					"type": "formula",
					"as": "availability",
					"expr": "(datum.total.doc_count > 0) ? ((datum.success.doc_count + datum.error_5xx.doc_count) / datum.total.doc_count) * 100 : null"
				},
				{
